#!/usr/bin/env node
/* Run after importing the catalog. PDF is generated by server.make_pdf separately. */
'use strict';
const fs=require('fs'),path=require('path');
const root=path.resolve(__dirname,'..'),E=require(path.join(root,'shared/engine.js'));
const lib=JSON.parse(fs.readFileSync(path.join(root,'assets/library.json'),'utf8'));
const project=E.makeDefaultProject(lib),manifest=E.layout(project,lib),assets={};
for(const section of manifest.sections){for(const layer of section.layers){for(const p of layer.placements){if(!assets[p.code]){const file=path.resolve(root,p.asset);if(!file.startsWith(root+path.sep))throw Error('Asset outside root');assets[p.code]='data:image/png;base64,'+fs.readFileSync(file).toString('base64');}}}}
const exchange=E.createExchange(project,lib,assets),out=path.join(root,'examples');fs.mkdirSync(out,{recursive:true});
fs.writeFileSync(path.join(out,'sample-project.json'),JSON.stringify(project,null,2)+'\n');
fs.writeFileSync(path.join(out,'sample.naqsh.json'),JSON.stringify(exchange,null,2)+'\n');
fs.writeFileSync(path.join(out,'sample-garment.svg'),E.renderSvg(manifest,assets,{guides:true,labels:false,background:'#ffffff'})+'\n');
console.log(JSON.stringify({sections:manifest.sections.length,placements:manifest.placementCount,usedCodes:Object.keys(assets),sheet:manifest.sheet}));
